def main(out, extra):
    rows=[]
    for i,e in enumerate(E+json.load(open(extra)) if extra else E, start=1):
        claim,val,unit,src,stype,period,q,notes = e
        rows.append(dict(evidence_id=f"EV-DEV-{i:03d}",claim=claim,value=val,unit=unit,source_url_or_path=src,source_type=stype,filing_period=period,accessed=A,quality=q,notes=notes))
    with open(out,'w') as f:
        for r in rows: f.write(json.dumps(r)+"\n")
    print(len(rows))
main(sys.argv[1], sys.argv[2] if len(sys.argv)>2 else None)
